    !> Undo and redo. A command is a text (shown as "Undo <text>") and an integer id
    !> of your choosing: `push(text, id)` records it and immediately calls the
    !> `redoRequested(id)` slots, which must perform it; undoing calls the
    !> `undoRequested(id)` slots, which must reverse it. Keep what each id needs
    !> (e.g. old and new values) in your own arrays. Menu actions that follow the
    !> stack: `createUndoAction` / `createRedoAction`.
    type, extends(QObject), public :: QUndoStack
        type(QSignalInt) :: redoRequested   !! Perform (or redo) the command with this id (also called by `push`).
        type(QSignalInt) :: undoRequested   !! Reverse the command with this id.
        type(QSignalBool) :: canUndoChanged   !! Whether undo is possible changed.
        type(QSignalBool) :: canRedoChanged   !! Whether redo is possible changed.
        type(QSignalInt) :: indexChanged   !! The current position in the stack changed.
        type(QSignalBool) :: cleanChanged   !! The stack became clean (saved state) or not.
        type(QSignalString) :: undoTextChanged   !! The text of the command `undo` would reverse changed.
        type(QSignalString) :: redoTextChanged   !! The text of the command `redo` would perform changed.
    contains
        procedure :: attach => qundostack_attach
        procedure :: push => qundostack_push
        procedure :: undo => qundostack_undo
        procedure :: redo => qundostack_redo
        procedure :: canUndo => qundostack_canUndo
        procedure :: canRedo => qundostack_canRedo
        procedure :: undoText => qundostack_undoText
        procedure :: redoText => qundostack_redoText
        procedure :: count => qundostack_count
        procedure :: index => qundostack_index
        procedure :: setIndex => qundostack_setIndex
        procedure :: text => qundostack_text
        procedure :: clear => qundostack_clear
        procedure :: setClean => qundostack_setClean
        procedure :: isClean => qundostack_isClean
        procedure :: setUndoLimit => qundostack_setUndoLimit
        procedure :: beginMacro => qundostack_beginMacro
        procedure :: endMacro => qundostack_endMacro
        procedure :: createUndoAction => qundostack_createUndoAction
        procedure :: createRedoAction => qundostack_createRedoAction
    end type QUndoStack
    !> Constructor: `QUndoStack([parent])`.
    interface QUndoStack
        module procedure :: qundostack_new
    end interface QUndoStack

    !> A list of the commands of an undo stack; clicking one undoes or redoes up to it.
    type, extends(QAbstractItemView), public :: QUndoView
    contains
        procedure :: setEmptyLabel => qundoview_setEmptyLabel
    end type QUndoView
    !> Constructor: `QUndoView(stack [, parent])`.
    interface QUndoView
        module procedure :: qundoview_new
    end interface QUndoView

    !> Forwards the events of any object -- a QWindow, a widget, a widget's
    !> viewport, the application -- to Fortran slots (`Qtf` marks a qt-fortran
    !> class). Create one per object: `events = QtfEventFilter(window)`; it is a
    !> child of the object, so it goes away with it.
    !>
    !> Input events (mouse, wheel, keys) can be consumed: they arrive marked
    !> ignored, and a slot that calls `event%accept()` stops the event there (the
    !> object never sees it); otherwise it continues as usual. The other events are
    !> only observed.
    !>
    !> Slots run on the thread the object belongs to (the GUI thread for windows
    !> and widgets).
    type, extends(QObject), public :: QtfEventFilter
        type(QSignalMouseEvent) :: mousePressEvent   !! Mouse button pressed (accept to consume).
        type(QSignalMouseEvent) :: mouseReleaseEvent   !! Mouse button released (accept to consume).
        type(QSignalMouseEvent) :: mouseMoveEvent   !! Mouse moved (accept to consume).
        type(QSignalMouseEvent) :: mouseDoubleClickEvent   !! Mouse button double-clicked (accept to consume).
        type(QSignalWheelEvent) :: wheelEvent   !! Wheel turned (accept to consume).
        type(QSignalKeyEvent) :: keyPressEvent   !! Key pressed (accept to consume).
        type(QSignalKeyEvent) :: keyReleaseEvent   !! Key released (accept to consume).
        type(QSignalResizeEvent) :: resizeEvent   !! The object was resized (logical pixels).
        type(QSignal) :: exposeEvent   !! A window was exposed or hidden on screen: check its `isExposed()`.
        type(QSignal) :: updateRequest   !! A window's `requestUpdate` came due: render a frame.
        type(QSignal) :: enterEvent   !! The mouse entered.
        type(QSignal) :: leaveEvent   !! The mouse left.
        type(QSignalInt) :: focusInEvent   !! Keyboard focus gained: the reason (a Qt_*FocusReason constant).
        type(QSignalInt) :: focusOutEvent   !! Keyboard focus lost: the reason.
        type(QSignal) :: showEvent   !! Shown.
        type(QSignal) :: hideEvent   !! Hidden.
        type(QSignal) :: surfaceCreated   !! A window's native surface was created (when it is first shown, or created again after `destroy`).
        type(QSignal) :: surfaceAboutToBeDestroyed   !! A window's native surface is about to be destroyed (`destroy`, re-parenting, the window deleted): a renderer drawing into it (e.g. through `winId`) must stop and release it now, before returning. Sent synchronously, while the surface still exists.
    contains
        procedure :: attach => qtfeventfilter_attach
    end type QtfEventFilter
    !> Constructor: `QtfEventFilter(target)`.
    interface QtfEventFilter
        module procedure :: qtfeventfilter_new
    end interface QtfEventFilter

    !> Constructor: `QApplication()`, with the program's command-line arguments.
    interface QApplication
        module procedure :: qapplication_new
    end interface QApplication

    abstract interface
        !> Slot providing one table cell: set its value with `request%setText` etc.
        subroutine qt_slot_model_data(row, column, request, data)
            import :: QtfModelRequest
            implicit none
            integer, intent(in) :: row, column
            type(QtfModelRequest), intent(inout) :: request
            class(*), intent(inout), optional :: data
        end subroutine qt_slot_model_data
        !> Slot receiving an edited table cell.
        subroutine qt_slot_model_edit(row, column, text, data)
            implicit none
            integer, intent(in) :: row, column
            character(len=*), intent(in) :: text
            class(*), intent(inout), optional :: data
        end subroutine qt_slot_model_edit
        !> Slot receiving a tree item.
        subroutine qt_slot_tree_item(item, data)
            import :: QTreeWidgetItem
            implicit none
            type(QTreeWidgetItem), intent(in) :: item
            class(*), intent(inout), optional :: data
        end subroutine qt_slot_tree_item
        !> Slot receiving a tree item and a column.
        subroutine qt_slot_tree_item_int(item, column, data)
            import :: QTreeWidgetItem
            implicit none
            type(QTreeWidgetItem), intent(in) :: item
            integer, intent(in) :: column
            class(*), intent(inout), optional :: data
        end subroutine qt_slot_tree_item_int
    end interface
    public :: qt_slot_model_data, qt_slot_model_edit, qt_slot_tree_item, qt_slot_tree_item_int

    !> Slot handler for QSignalModelData.
    type, extends(qt_slot_handler) :: model_data_handler
        procedure(qt_slot_model_data), pointer, nopass :: f => null()
    contains
        procedure :: invoke => model_data_handler_invoke
    end type model_data_handler

    !> Slot handler for QSignalModelEdit.
