contains

    !> The command-line arguments left after Qt removed its own options (the first is the program); `args(i)%s` is the i-th.
    function QApplication_arguments() result(res)
        type(qt_string), allocatable :: res(:)
        integer(c_int) :: n_
        type(c_ptr) :: p_
        p_ = qtf_qapplication_arguments(n_)
        res = qtf_take_string_list(p_, n_)
    end function QApplication_arguments

    !> Run the event loop until quit; returns the exit code.
    function QApplication_exec() result(res)
        integer :: res
        res = qtf_qapplication_exec()
    end function QApplication_exec

    !> Ask the event loop to exit (`exec` then returns 0).
    subroutine QApplication_quit()
        call qtf_qapplication_quit()
    end subroutine QApplication_quit

    !> Process pending events, then return.
    subroutine QApplication_processEvents()
        call qtf_qapplication_processEvents()
    end subroutine QApplication_processEvents

    !> The active modal dialog (null if none).
    function QApplication_activeModalWidget() result(res)
        type(QWidget) :: res
        call res%attach(qtf_qapplication_activeModalWidget())
    end function QApplication_activeModalWidget

    !> Set an application attribute (a Qt_AA_* constant); some must be set before the application is created.
    subroutine QApplication_setAttribute(attribute, on)
        integer, intent(in) :: attribute
        logical, intent(in), optional :: on
        logical :: on_
        on_ = .true.
        if (present(on)) on_ = on
        call qtf_qapplication_setAttribute(int(attribute, c_int), qtf_int(on_))
    end subroutine QApplication_setAttribute

    !> True if an application attribute is set.
    function QApplication_testAttribute(attribute) result(res)
        integer, intent(in) :: attribute
        logical :: res
        res = qtf_logical(qtf_qapplication_testAttribute(int(attribute, c_int)))
    end function QApplication_testAttribute

    !> Set the organization name (used by QSettings to find the settings).
    subroutine QApplication_setOrganizationName(name)
        character(len=*), intent(in) :: name
        call qtf_qapplication_setOrganizationName(name, len(name, c_int))
    end subroutine QApplication_setOrganizationName

    !> The organization name.
    function QApplication_organizationName() result(res)
        character(len=:), allocatable :: res
        integer(c_int) :: n_
        type(c_ptr) :: p_
        p_ = qtf_qapplication_organizationName(n_)
        res = qtf_take_string(p_, n_)
    end function QApplication_organizationName

    !> Set the organization's Internet domain (used by QSettings on macOS).
    subroutine QApplication_setOrganizationDomain(domain)
        character(len=*), intent(in) :: domain
        call qtf_qapplication_setOrganizationDomain(domain, len(domain, c_int))
    end subroutine QApplication_setOrganizationDomain

    !> Set the application name (used by QSettings and in dialogs).
    subroutine QApplication_setApplicationName(name)
        character(len=*), intent(in) :: name
        call qtf_qapplication_setApplicationName(name, len(name, c_int))
    end subroutine QApplication_setApplicationName

    !> The application name.
    function QApplication_applicationName() result(res)
        character(len=:), allocatable :: res
        integer(c_int) :: n_
        type(c_ptr) :: p_
        p_ = qtf_qapplication_applicationName(n_)
        res = qtf_take_string(p_, n_)
    end function QApplication_applicationName

    !> Bind to a C++ QWidget and its signals.
    subroutine qwidget_attach(self, ptr)
        class(QWidget), intent(inout) :: self
        type(c_ptr), intent(in) :: ptr
        call self%QObject%attach(ptr)
        self%closeEvent = QSignalCloseEvent(ptr, QTF_SIG_QWIDGET_CLOSEEVENT, self%serial)
        self%contextMenuEvent = QSignalContextMenuEvent(ptr, QTF_SIG_QWIDGET_CONTEXTMENUEVENT, self%serial)
        self%enterEvent = QSignal(ptr, QTF_SIG_QWIDGET_ENTEREVENT, self%serial)
        self%leaveEvent = QSignal(ptr, QTF_SIG_QWIDGET_LEAVEEVENT, self%serial)
        self%focusInEvent = QSignalInt(ptr, QTF_SIG_QWIDGET_FOCUSINEVENT, self%serial)
        self%focusOutEvent = QSignalInt(ptr, QTF_SIG_QWIDGET_FOCUSOUTEVENT, self%serial)
        self%showEvent = QSignal(ptr, QTF_SIG_QWIDGET_SHOWEVENT, self%serial)
        self%hideEvent = QSignal(ptr, QTF_SIG_QWIDGET_HIDEEVENT, self%serial)
    end subroutine qwidget_attach

    !> Create a widget; without a parent it is a top-level window.
    function qwidget_new(parent) result(res)
        class(QWidget), intent(in), optional :: parent
        type(QWidget) :: res
        call res%attach(qtf_qwidget_new(qtf_ptr(parent)))
    end function qwidget_new

