        class(QWidget), intent(in), optional :: parent
        type(QWidget) :: res
        call res%attach(qtf_qwidget_createWindowContainer(qtf_live(window, 'QWidget%createWindowContainer'), &
                qtf_ptr(parent)))
    end function QWidget_createWindowContainer

