    !> Move the widget (a window: on the screen).
    subroutine qwidget_move(self, x, y)
        class(QWidget), intent(in) :: self
        integer, intent(in) :: x
        integer, intent(in) :: y
        call qtf_qwidget_move(qtf_live(self, 'QWidget%move'), int(x, c_int), int(y, c_int))
