    !> Create a label showing `text`.
    function qlabel_new(text, parent) result(res)
        character(len=*), intent(in), optional :: text
        class(QWidget), intent(in), optional :: parent
        type(QLabel) :: res
        character(len=:), allocatable :: text_
        text_ = ''
        if (present(text)) text_ = text
        call res%attach(qtf_qlabel_new(text_, len(text_, c_int), qtf_ptr(parent)))
    end function qlabel_new

    !> Set the label text (plain or rich text).
    subroutine qlabel_setText(self, text)
        class(QLabel), intent(in) :: self
        character(len=*), intent(in) :: text
        call qtf_qlabel_setText(qtf_live(self, 'QLabel%setText'), text, len(text, c_int))
    end subroutine qlabel_setText

    !> The label text.
    function qlabel_text(self) result(res)
        class(QLabel), intent(in) :: self
        character(len=:), allocatable :: res
        integer(c_int) :: n_
        type(c_ptr) :: p_
        p_ = qtf_qlabel_text(qtf_live(self, 'QLabel%text'), n_)
        res = qtf_take_string(p_, n_)
    end function qlabel_text

