    !> Add several items; trailing blanks of each element are trimmed.
    subroutine qcombobox_addItems(self, texts)
        class(QComboBox), intent(in) :: self
        character(len=*), intent(in) :: texts(:)
        integer :: i
        do i = 1, size(texts)
            call self%addItem(trim(texts(i)))
        end do
