    !> Modal question box (default buttons Yes|No); returns the standard button clicked.
    function QMessageBox_question(title, text, buttons, defaultButton, parent) result(res)
        character(len=*), intent(in) :: title
        character(len=*), intent(in) :: text
        integer, intent(in), optional :: buttons
        integer, intent(in), optional :: defaultButton
        class(QWidget), intent(in), optional :: parent
        integer :: res
        integer(c_int) :: buttons_
        integer(c_int) :: defaultButton_
        buttons_ = ior(QMessageBox_Yes, QMessageBox_No)
        if (present(buttons)) buttons_ = int(buttons, c_int)
        defaultButton_ = QMessageBox_NoButton
        if (present(defaultButton)) defaultButton_ = int(defaultButton, c_int)
        res = qtf_qmessagebox_question(title, len(title, c_int), text, len(text, c_int), buttons_, defaultButton_, &
                qtf_ptr(parent))
    end function QMessageBox_question

    !> A file dialog (configure, then `exec`).
    function qfiledialog_new(caption, directory, filter, parent) result(res)
        character(len=*), intent(in), optional :: caption
        character(len=*), intent(in), optional :: directory
        character(len=*), intent(in), optional :: filter
        class(QWidget), intent(in), optional :: parent
        type(QFileDialog) :: res
        character(len=:), allocatable :: caption_
        character(len=:), allocatable :: directory_
        character(len=:), allocatable :: filter_
        caption_ = ''
        if (present(caption)) caption_ = caption
        directory_ = ''
        if (present(directory)) directory_ = directory
        filter_ = ''
        if (present(filter)) filter_ = filter
        call res%attach(qtf_qfiledialog_new(caption_, len(caption_, c_int), directory_, len(directory_, c_int), &
                filter_, len(filter_, c_int), qtf_ptr(parent)))
    end function qfiledialog_new

