    !> Modal "open file" dialog; returns the chosen path, or '' if cancelled.
    function QFileDialog_getOpenFileName(caption, dir, filter, parent, options) result(res)
        character(len=*), intent(in), optional :: caption
        character(len=*), intent(in), optional :: dir
        character(len=*), intent(in), optional :: filter
        class(QWidget), intent(in), optional :: parent
        integer, intent(in), optional :: options
        character(len=:), allocatable :: res
        character(len=:), allocatable :: caption_
        character(len=:), allocatable :: dir_
        character(len=:), allocatable :: filter_
        integer(c_int) :: options_
        integer(c_int) :: n_
        type(c_ptr) :: p_
        caption_ = ''
        if (present(caption)) caption_ = caption
        dir_ = ''
        if (present(dir)) dir_ = dir
        filter_ = ''
        if (present(filter)) filter_ = filter
        options_ = 0
        if (present(options)) options_ = int(options, c_int)
        p_ = qtf_qfiledialog_getOpenFileName(caption_, len(caption_, c_int), dir_, len(dir_, c_int), filter_, &
                len(filter_, c_int), qtf_ptr(parent), options_, n_)
        res = qtf_take_string(p_, n_)
    end function QFileDialog_getOpenFileName

    !> Modal "open files" dialog; returns the chosen paths (empty if cancelled).
