    !> Modal directory chooser; returns the chosen directory, or '' if cancelled.
    function QFileDialog_getExistingDirectory(caption, dir, parent, options) result(res)
        character(len=*), intent(in), optional :: caption
        character(len=*), intent(in), optional :: dir
