        integer(c_int) :: column_
        column_ = 0
        if (present(column)) column_ = int(column, c_int)
        res = qtf_qsortfilterproxymodel_mapFromSourceRow(qtf_live(self, 'QSortFilterProxyModel%mapFromSourceRow'), &
                int(row, c_int), column_)
