        class(QFileSystemModel), intent(in) :: self
        character(len=:), allocatable :: res
        integer(c_int) :: n_
        type(c_ptr) :: p_
        p_ = qtf_qfilesystemmodel_rootPath(qtf_live(self, 'QFileSystemModel%rootPath'), n_)
        res = qtf_take_string(p_, n_)
