        type(c_ptr), intent(in) :: ptr
        call self%QWidget%attach(ptr)
        self%messageChanged = QSignalString(ptr, QTF_SIG_QSPLASHSCREEN_MESSAGECHANGED, self%serial)
    end subroutine qsplashscreen_attach

