    !> Bind to a C++ QtfEventFilter and its signals.
    subroutine qtfeventfilter_attach(self, ptr)
        class(QtfEventFilter), intent(inout) :: self
        type(c_ptr), intent(in) :: ptr
        call self%QObject%attach(ptr)
        self%mousePressEvent = QSignalMouseEvent(ptr, QTF_SIG_QTFEVENTFILTER_MOUSEPRESSEVENT, self%serial)
        self%mouseReleaseEvent = QSignalMouseEvent(ptr, QTF_SIG_QTFEVENTFILTER_MOUSERELEASEEVENT, self%serial)
        self%mouseMoveEvent = QSignalMouseEvent(ptr, QTF_SIG_QTFEVENTFILTER_MOUSEMOVEEVENT, self%serial)
        self%mouseDoubleClickEvent = QSignalMouseEvent(ptr, QTF_SIG_QTFEVENTFILTER_MOUSEDOUBLECLICKEVENT, self%serial)
        self%wheelEvent = QSignalWheelEvent(ptr, QTF_SIG_QTFEVENTFILTER_WHEELEVENT, self%serial)
        self%keyPressEvent = QSignalKeyEvent(ptr, QTF_SIG_QTFEVENTFILTER_KEYPRESSEVENT, self%serial)
        self%keyReleaseEvent = QSignalKeyEvent(ptr, QTF_SIG_QTFEVENTFILTER_KEYRELEASEEVENT, self%serial)
        self%resizeEvent = QSignalResizeEvent(ptr, QTF_SIG_QTFEVENTFILTER_RESIZEEVENT, self%serial)
        self%exposeEvent = QSignal(ptr, QTF_SIG_QTFEVENTFILTER_EXPOSEEVENT, self%serial)
        self%updateRequest = QSignal(ptr, QTF_SIG_QTFEVENTFILTER_UPDATEREQUEST, self%serial)
        self%enterEvent = QSignal(ptr, QTF_SIG_QTFEVENTFILTER_ENTEREVENT, self%serial)
        self%leaveEvent = QSignal(ptr, QTF_SIG_QTFEVENTFILTER_LEAVEEVENT, self%serial)
        self%focusInEvent = QSignalInt(ptr, QTF_SIG_QTFEVENTFILTER_FOCUSINEVENT, self%serial)
        self%focusOutEvent = QSignalInt(ptr, QTF_SIG_QTFEVENTFILTER_FOCUSOUTEVENT, self%serial)
        self%showEvent = QSignal(ptr, QTF_SIG_QTFEVENTFILTER_SHOWEVENT, self%serial)
        self%hideEvent = QSignal(ptr, QTF_SIG_QTFEVENTFILTER_HIDEEVENT, self%serial)
        self%surfaceCreated = QSignal(ptr, QTF_SIG_QTFEVENTFILTER_SURFACECREATED, self%serial)
        self%surfaceAboutToBeDestroyed = QSignal(ptr, QTF_SIG_QTFEVENTFILTER_SURFACEABOUTTOBEDESTROYED, self%serial)
    end subroutine qtfeventfilter_attach

    !> Forward the events of `target`.
    function qtfeventfilter_new(target) result(res)
        class(QObject), intent(in) :: target
        type(QtfEventFilter) :: res
        call res%attach(qtf_qtfeventfilter_new(qtf_live(target, 'QtfEventFilter%new')))
    end function qtfeventfilter_new

    !> Create the application object, passing the program's command-line
    !> arguments to Qt (trailing blanks of each argument are dropped), or return
    !> the existing one.
    function qapplication_new() result(app)
        type(QApplication) :: app
        character(len=:), allocatable :: args(:)
        integer :: i, n, l, maxlen
        n = command_argument_count()
        maxlen = 1
        do i = 0, n
            call get_command_argument(i, length=l)
            maxlen = max(maxlen, l)
        end do
        allocate(character(len=maxlen) :: args(0:n))
        do i = 0, n
            call get_command_argument(i, args(i))
        end do
        call app%attach(qtf_qapplication_new_args(args, len(args, c_int), int(n + 1, c_int)))
    end function qapplication_new

    !> Connect a slot (with optional user data) to this signal.
    subroutine qsignalmodeldata_connect(self, slot, data, connection)
        class(QSignalModelData), intent(in) :: self
        procedure(qt_slot_model_data) :: slot
        class(*), intent(inout), target, optional :: data
        type(QMetaObject_Connection), intent(out), optional :: connection   !! to disconnect it later
        type(model_data_handler) :: h
        h%f => slot
        call qt_connect_handler(self, h, data, connection)
    end subroutine qsignalmodeldata_connect

    !> Call the slot with (row, column, request).
    subroutine model_data_handler_invoke(self, args, data)
        class(model_data_handler), intent(in) :: self
        type(qtf_args), intent(in) :: args
        class(*), pointer, intent(in) :: data
        type(QtfModelRequest) :: request
        request%ptr = args%p
        if (associated(data)) then
            call self%f(int(args%i(1)), int(args%i(2)), request, data)
        else
            call self%f(int(args%i(1)), int(args%i(2)), request)
        end if
    end subroutine model_data_handler_invoke

    !> Connect a slot (with optional user data) to this signal.
    subroutine qsignalmodeledit_connect(self, slot, data, connection)
        class(QSignalModelEdit), intent(in) :: self
        procedure(qt_slot_model_edit) :: slot
        class(*), intent(inout), target, optional :: data
        type(QMetaObject_Connection), intent(out), optional :: connection   !! to disconnect it later
        type(model_edit_handler) :: h
        h%f => slot
        call qt_connect_handler(self, h, data, connection)
    end subroutine qsignalmodeledit_connect

    !> Call the slot with (row, column, text).
    subroutine model_edit_handler_invoke(self, args, data)
        class(model_edit_handler), intent(in) :: self
        type(qtf_args), intent(in) :: args
        class(*), pointer, intent(in) :: data
        if (associated(data)) then
            call self%f(int(args%i(1)), int(args%i(2)), qtf_string(args%s, args%slen), data)
        else
            call self%f(int(args%i(1)), int(args%i(2)), qtf_string(args%s, args%slen))
        end if
    end subroutine model_edit_handler_invoke

    !> Connect a slot (with optional user data) to this signal.
    subroutine qsignaltreeitem_connect(self, slot, data, connection)
        class(QSignalTreeItem), intent(in) :: self
        procedure(qt_slot_tree_item) :: slot
        class(*), intent(inout), target, optional :: data
        type(QMetaObject_Connection), intent(out), optional :: connection   !! to disconnect it later
        type(tree_item_handler) :: h
        h%f => slot
        call qt_connect_handler(self, h, data, connection)
    end subroutine qsignaltreeitem_connect

    !> Call the slot with the item (null if none).
    subroutine tree_item_handler_invoke(self, args, data)
        class(tree_item_handler), intent(in) :: self
        type(qtf_args), intent(in) :: args
        class(*), pointer, intent(in) :: data
        type(QTreeWidgetItem) :: item
        item%ptr = args%p
        if (associated(data)) then
            call self%f(item, data)
        else
            call self%f(item)
        end if
    end subroutine tree_item_handler_invoke

    !> Connect a slot (with optional user data) to this signal.
    subroutine qsignaltreeitemint_connect(self, slot, data, connection)
        class(QSignalTreeItemInt), intent(in) :: self
        procedure(qt_slot_tree_item_int) :: slot
        class(*), intent(inout), target, optional :: data
        type(QMetaObject_Connection), intent(out), optional :: connection   !! to disconnect it later
        type(tree_item_int_handler) :: h
        h%f => slot
        call qt_connect_handler(self, h, data, connection)
    end subroutine qsignaltreeitemint_connect

    !> Call the slot with the item and column.
    subroutine tree_item_int_handler_invoke(self, args, data)
        class(tree_item_int_handler), intent(in) :: self
        type(qtf_args), intent(in) :: args
        class(*), pointer, intent(in) :: data
        type(QTreeWidgetItem) :: item
        item%ptr = args%p
        if (associated(data)) then
            call self%f(item, int(args%i(1)), data)
        else
            call self%f(item, int(args%i(1)))
        end if
    end subroutine tree_item_int_handler_invoke

    !> Modal font chooser; returns the chosen font, or the initial one if
    !> cancelled (then `ok` is false).
    function QFontDialog_getFont(initial, title, ok, parent) result(font)
        type(QFont), intent(in), optional :: initial
        character(len=*), intent(in), optional :: title
        logical, intent(out), optional :: ok
        class(QWidget), intent(in), optional :: parent
        type(QFont) :: font
        type(QFont) :: f0
        character(len=:), allocatable :: t
        integer(c_int) :: ok_, bold, italic, n
        real(c_double) :: size
        type(c_ptr) :: p
        if (present(initial)) f0 = initial
        if (.not. allocated(f0%family)) f0%family = ''
        t = ''
        if (present(title)) t = title
        p = qtf_qfontdialog_getFont(qtf_ptr(parent), f0%family, len(f0%family, c_int), f0%pointSize, &
                                    qtf_int(f0%bold), qtf_int(f0%italic), t, len(t, c_int), ok_, size, &
                                    bold, italic, n)
        font%family = qtf_take_string(p, n)
        font%pointSize = size
        font%bold = qtf_logical(bold)
        font%italic = qtf_logical(italic)
        if (present(ok)) ok = qtf_logical(ok_)
    end function QFontDialog_getFont

end module qt_widgets
